// FORM / AI — all logic runs in this browser. No trackers, analytics calls or AI APIs.
const ALL_DAYS = WEEKS.flatMap(w => w.days);
const NAV = [
  ['dashboard','Overview','layout-dashboard'],['roadmap','Curriculum','map'],['learn','Daily lessons','book-open'],
  ['labs','Interactive labs','flask-conical'],['projects','Weekly projects','folder-kanban'],
  ['resources','Reference library','library-big'],['analytics','Analytics','chart-no-axes-combined'],['readiness','Readiness assessment','graduation-cap'],
  ['notebook','My notebook','notebook-pen'],['settings','Settings & backup','settings-2']
];
const SKILLS = [
 ['python','Python & numerical computing','Implement vectorized calculations and a data pipeline.',1],
 ['math','Mathematics & optimization','Derive and verify the gradient of a small loss.',1],
 ['pytorch','PyTorch & deep learning','Train and evaluate a small neural network.',2],
 ['transformer','Transformers and LLMs','Explain attention and load a matching tokenizer/model.',3],
 ['finetune','Model adaptation','Produce a LoRA adapter and test it on held-out data.',5],
 ['evaluation','Evaluation & retention','Construct old/new benchmarks and analyze regressions.',6],
 ['mlops','MLOps and research rigor','Version datasets, checkpoints, runs and metrics.',8]
];
const LABS = [
 {id:'tensor',title:'Tensor shape explorer',icon:'grid-3x3',week:1,desc:'Dimensions, total elements, and rough tensor memory.'},
 {id:'gradient',title:'Gradient descent simulator',icon:'trending-down',week:2,desc:'Observe weight updates, convergence, and divergence.'},
 {id:'tokenizer',title:'Tokenization explorer',icon:'whole-word',week:3,desc:'Compare character, whitespace, and toy subword splitting.'},
 {id:'attention',title:'Attention softmax lab',icon:'network',week:4,desc:'Inspect attention probabilities from score changes.'},
 {id:'lora',title:'LoRA parameter calculator',icon:'calculator',week:5,desc:'Estimate update matrix size and trainable parameters.'},
 {id:'forgetting',title:'Continual learning metric lab',icon:'git-compare',week:7,desc:'Measure old-task forgetting and new-task improvement.'}
];
const FLOW = [
 ['data','Data','Define and version old/new task samples, keep held-out tests independent.'],
 ['base','Baseline','Freeze an existing model revision and measure unchanged performance.'],
 ['route','Strategy','Choose RAG, LoRA, QLoRA, continued pretraining or a newer-model comparator.'],
 ['evaluate','Evaluate','Score updated and old tasks, loss regressions, latency, and cost.'],
 ['decide','Decision','Recommend retain, upgrade, specialize, archive or replace using explicit constraints.'],
 ['monitor','Monitor','Recheck current tasks over time and trigger a new evaluated cycle when drift appears.']
];
const defaultState = () => ({version:1,theme:'light',settings:{focusMinutes:25,sound:true},days:{},projects:{},readiness:{},labs:{},labValues:{},minutes:{},createdAt:new Date().toISOString(),lastSaved:null});
let state=defaultState(), storageMode='Starting…', db=null, saveTimer=null;
let ui={route:'dashboard',day:'d1',tab:'overview',week:1,lab:'tensor',search:'',flow:'base',projectOpen:1,filter:'all'};
let timer={remaining:25*60,duration:25*60,running:false,deadline:0,interval:null};
const E = s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const I = name => `<i aria-hidden="true" data-lucide="${E(name)}"></i>`;
const fmt = n=>Number(n).toLocaleString('en-US');
const percent=(a,b)=>b?Math.round(100*a/b):0;
const dayState=id=>state.days[id]||(state.days[id]={learned:false,steps:[false,false,false],quizPassed:false,choice:null,wrong:0,notes:'',bookmarked:false,completedAt:null});
const projectState=id=>state.projects[id]||(state.projects[id]={tasks:[false,false,false,false],notes:'',evidence:''});
const dayParts=id=>{const x=dayState(id);return [!!x.learned,x.steps.every(Boolean),!!x.quizPassed]};
const done=id=>dayParts(id).every(Boolean);
const weekDone = number=>WEEKS[number-1].days.filter(d=>done(d.id)).length;
const projectDone = number => projectState('w'+number).tasks.every(Boolean);
const countDone=()=>ALL_DAYS.filter(d=>done(d.id)).length;
const countProjectDone=()=>WEEKS.filter(w=>projectDone(w.number)).length;
const minutesAll=()=>Object.values(state.minutes).reduce((a,b)=>a+(Number(b)||0),0);
const progressBar = (n,max)=>`<div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,percent(n,max)))}%"></div></div>`;
const status = (id)=>done(id)?'Completed':(dayParts(id).some(Boolean)?'In progress':'Not started');
const pageTitle=()=>({dashboard:'Overview',roadmap:'Curriculum',learn:'Daily lessons',labs:'Interactive labs',projects:'Weekly projects',resources:'References',analytics:'Analytics',readiness:'Readiness assessment',notebook:'Notebook',settings:'Settings',search:'Search lessons'})[ui.route]||'Overview';
function isSafeURL(raw){try{const u=new URL(raw);return ['https:','http:'].includes(u.protocol)}catch{return false}}
function resourceLink(name,href){return isSafeURL(href)?`<a class="inline-link" href="${E(href)}" target="_blank" rel="noopener noreferrer">${E(name)} ↗</a>`:E(name)}
function iconRefresh(){if(window.lucide&&typeof lucide.createIcons==='function'){try{lucide.createIcons()}catch(e){console.warn('Icon enhancement failed',e)}}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast._timer);toast._timer=setTimeout(()=>t.classList.remove('show'),2600)}
function applyTheme(){document.documentElement.dataset.theme=state.theme==='dark'?'dark':'light'}
function openDb(){return new Promise((resolve,reject)=>{try{if(!window.indexedDB){reject(new Error('IndexedDB unavailable'));return}const req=indexedDB.open('form-ai-learning-lms',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('kv'))req.result.createObjectStore('kv')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('IndexedDB blocked'))}catch(err){reject(err)}})}
function idbGet(){return new Promise((resolve,reject)=>{try{const req=db.transaction('kv','readonly').objectStore('kv').get('progress');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}catch(err){reject(err)}})}
function idbSet(value){return new Promise((resolve,reject)=>{try{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(value,'progress');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)}catch(err){reject(err)}})}
function validateImport(obj){return obj&&typeof obj==='object'&&!Array.isArray(obj)&&obj.version===1&&typeof obj.days==='object'&&obj.days!==null&&typeof obj.projects==='object'&&obj.projects!==null}
function normalizeState(input){const clean=defaultState();if(!validateImport(input))return clean;clean.theme=input.theme==='dark'?'dark':'light';clean.createdAt=typeof input.createdAt==='string'?input.createdAt:clean.createdAt;
 for(const d of ALL_DAYS){const src=input.days[d.id];if(src&&typeof src==='object'){clean.days[d.id]={learned:!!src.learned,steps:Array.from({length:3},(_,i)=>!!(Array.isArray(src.steps)&&src.steps[i])),quizPassed:!!src.quizPassed,choice:Number.isInteger(src.choice)?src.choice:null,wrong:Math.max(0,Math.min(999,Number(src.wrong)||0)),notes:String(src.notes||'').slice(0,12000),bookmarked:!!src.bookmarked,completedAt:typeof src.completedAt==='string'?src.completedAt:null}}}
 for(const w of WEEKS){const src=input.projects[w.id];if(src&&typeof src==='object'){clean.projects[w.id]={tasks:Array.from({length:4},(_,i)=>!!(Array.isArray(src.tasks)&&src.tasks[i])),notes:String(src.notes||'').slice(0,12000),evidence:String(src.evidence||'').slice(0,1200)}}}
 for(const skill of SKILLS)clean.readiness[skill[0]]=Math.max(0,Math.min(3,Number.isInteger(Number(input.readiness?.[skill[0]]))?Number(input.readiness?.[skill[0]]):0));
 for(const lab of LABS)clean.labs[lab.id]=!!input.labs?.[lab.id];
 for(const d of ALL_DAYS){if(Number.isFinite(Number(input.minutes?.[d.id])))clean.minutes[d.id]=Math.min(99999,Math.max(0,Number(input.minutes[d.id])))}
 clean.labValues=(input.labValues&&typeof input.labValues==='object'&&!Array.isArray(input.labValues))?input.labValues:{};
 clean.settings={focusMinutes:Math.min(120,Math.max(1,Math.round(Number(input.settings?.focusMinutes)||25))),sound:input.settings?.sound!==false};
 return clean}
async function initPersistence(){try{db=await openDb();storageMode='IndexedDB';const loaded=await idbGet();if(loaded)state=normalizeState(loaded)}catch(err){console.warn('IndexedDB unavailable; attempting localStorage:',err);try{storageMode='localStorage fallback';const old=localStorage.getItem('form-ai-learning-lms');if(old)state=normalizeState(JSON.parse(old))}catch(e){storageMode='Memory only (export often)';console.warn('Local persistence unavailable:',e)}}
 timer.duration=timer.remaining=(state.settings?.focusMinutes||25)*60;
 applyTheme();if(location.hash&&location.hash!=='#')applyRoute();else render();startTimerTicker()}
function save(){state.lastSaved=new Date().toISOString();clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{if(storageMode==='IndexedDB')await idbSet(state);else if(storageMode==='localStorage fallback')localStorage.setItem('form-ai-learning-lms',JSON.stringify(state));document.getElementById('storageStatus').textContent=storageMode==='IndexedDB'?'Saved on device':'Storage: '+storageMode}catch(e){console.error('Progress save failed:',e);storageMode='Memory only (export often)';document.getElementById('storageStatus').textContent='Save failed — export backup';toast('Saving failed. Export a backup from Settings.')}},180)}
function changeDay(id,mutator){const d=dayState(id),before=done(id);mutator(d);const now=done(id);if(now&&!before){d.completedAt=new Date().toISOString();toast('Lesson complete. Nice work.')}if(!now&&before)d.completedAt=null;save();render()}
function nextLesson(){return ALL_DAYS.find(d=>!done(d.id))||ALL_DAYS.at(-1)}
function coach(){for(const d of ALL_DAYS){if(done(d.id))continue;const s=dayState(d.id),parts=dayParts(d.id);if(parts[0]&&!parts[1])return{label:'Practice backlog',title:d.title,text:'You marked the concept learned. Finish its guided practice and verify the result.',day:d,tab:'practice'};if(parts[1]&&!parts[2])return{label:'Assessment pending',title:d.title,text:'You have practiced this concept. Pass its knowledge check to complete the lesson.',day:d,tab:'quiz'};if(s.wrong>=2&&!s.quizPassed)return{label:'Review recommended',title:d.title,text:'This question has needed several attempts. Review the explanation before trying again.',day:d,tab:'overview'};return{label:'Recommended next lesson',title:d.title,text:`Day ${d.number} · Week ${d.week}. Read, practice, and pass the check to record completion.`,day:d,tab:'overview'}}
 return{label:'Core lessons complete',title:'Your learning path is finished',text:'Review projects and your research capstone. Retest any topics you cannot explain independently.',day:ALL_DAYS.at(-1),tab:'overview'}}
function renderNav(){const links=NAV.map(([route,label,icon],idx)=>`${route==='dashboard'||route==='labs'||route==='settings'?`<div class="nav-label">${route==='dashboard'?'Study workspace':route==='labs'?'Your research':'Account'}</div>`:''}<button class="nav-item ${route===ui.route?'active':''}" data-action="nav" data-route="${route}" ${route===ui.route?'aria-current="page"':''}>${I(icon)}<span>${E(label)}</span>${route==='learn'?`<span class="nav-count">${countDone()}/63</span>`:''}</button>`).join('');document.getElementById('nav').innerHTML=links;
 document.getElementById('sidefoot').innerHTML=`<div class="between flex gap-2 items-center" style="margin-bottom:10px"><span class="upper">Overall progress</span><span class="strong sm">${countDone()}/63</span></div>${progressBar(countDone(),63)}<p class="tiny muted" style="margin:12px 0 0">8 core weeks + optional research capstone.</p>`;
 function crumbTrail(){const parts=['FORM / AI',pageTitle()];if(['learn','roadmap','projects'].includes(ui.route))parts.push(`Week ${ui.week}`);if(ui.route==='learn'){const d=ALL_DAYS.find(x=>x.id===ui.day);if(d)parts.push(d.title.length>34?d.title.slice(0,34)+'…':d.title)}if(ui.route==='labs'){const l=LABS.find(x=>x.id===ui.lab);if(l)parts.push(l.title)}return parts.map((p,i)=>i===parts.length-1?`<b>${E(p)}</b>`:E(p)).join('<span style="margin:0 8px">/</span>')}
 document.getElementById('breadcrumb').innerHTML=crumbTrail();document.getElementById('storageStatus').textContent=storageMode==='IndexedDB'?'IndexedDB · local':storageMode}
function pageHead(kicker,title,subtitle,extra=''){return`<header class="page-heading"><div><div class="eyebrow">${E(kicker)}</div><h1 class="h1">${E(title)}</h1><p class="subtitle">${E(subtitle)}</p></div>${extra}</header>`}
function render(){renderNav();const screens={dashboard:renderDashboard,roadmap:renderRoadmap,learn:renderLearn,labs:renderLabs,projects:renderProjects,resources:renderResources,analytics:renderAnalytics,readiness:renderReadiness,search:renderSearch,notebook:renderNotebook,settings:renderSettings};document.getElementById('app').innerHTML=(screens[ui.route]||renderDashboard)();iconRefresh();if(ui.route==='dashboard'||ui.route==='analytics')setTimeout(drawProgressChart,0);if(ui.route==='labs')updateLabOutput();updateTimerUI();}
/* ---- Nested slug routes (hash based so the app also works from file://) ----
   #/learn/week-2/<day-slug>/<tab> · #/learn/<week-slug> · #/roadmap/week-3
   #/labs/<lab-id> · #/projects/week-4 · plus simple #/dashboard, #/settings … */
const slugify=s=>String(s||'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/-{2,}/g,'-').replace(/^-+|-+$/g,'');
const WEEK_SLUGS=WEEKS.map(w=>slugify(w.title));
const DAY_SLUGS={};for(const w of WEEKS){const used=new Set();for(const d of w.days){let base=slugify(d.title)||`day-${d.dayInWeek}`;let s=base,n=2;while(used.has(s))s=`${base}-${n++}`;used.add(s);DAY_SLUGS[d.id]=s}}
const LEARN_TABS=['overview','practice','quiz','resources','notes'];
const SIMPLE_ROUTES=['dashboard','resources','analytics','readiness','notebook','settings','search'];
function weekFromSlug(token){if(!token)return null;const m=/^week-(\d{1,2})$/.exec(token);const n=m?Number(m[1]):WEEK_SLUGS.indexOf(token)+1;return n>=1&&n<=WEEKS.length?n:null}
function parseHash(){const segs=decodeURIComponent((location.hash||'')).replace(/^#\/?/,'').split('/').filter(Boolean);const out={route:'dashboard',params:{}};if(!segs.length)return out;const r=segs[0];
 if(r==='roadmap'||r==='projects'){out.route=r;const w=weekFromSlug(segs[1]);if(w)out.params.week=w}
 else if(r==='learn'){out.route='learn';const w=weekFromSlug(segs[1]);if(w){out.params.week=w;const day=WEEKS[w-1].days.find(d=>DAY_SLUGS[d.id]===segs[2]||segs[2]===`day-${d.dayInWeek}`||segs[2]===`day-${d.number}`);if(day){out.params.day=day.id;if(LEARN_TABS.includes(segs[3]))out.params.tab=segs[3]}}}
 else if(r==='labs'){out.route='labs';if(LABS.some(l=>l.id===segs[1]))out.params.lab=segs[1]}
 else if(SIMPLE_ROUTES.includes(r))out.route=r;
 return out}
function buildHash(route,p={}){if(route==='learn'){const d=ALL_DAYS.find(x=>x.id===p.day);const wSeg=`week-${p.week||d?.week||ui.week||1}`;if(d){let h=`#/learn/${wSeg}/${DAY_SLUGS[d.id]||'day-'+d.number}`;if(p.tab&&LEARN_TABS.includes(p.tab))h+=`/${p.tab}`;return h}return p.week?`#/learn/${wSeg}`:'#/learn'}
 if(route==='roadmap'||route==='projects')return p.week?`#/${route}/week-${p.week}`:`#/${route}`;
 if(route==='labs')return p.lab&&LABS.some(l=>l.id===p.lab)?`#/labs/${p.lab}`:'#/labs';
 return `#/${SIMPLE_ROUTES.includes(route)?route:'dashboard'}`}
function navigate(route,params={}){const target=buildHash(route,params);if((location.hash||'')===target)applyRoute();else location.hash=target}
function applyRoute(){const{route,params}=parseHash();if(params.week){ui.week=params.week;if(route==='learn'){if(params.day){ui.day=params.day;ui.tab=params.tab||'overview'}else{ui.day=WEEKS[ui.week-1].days[0].id;ui.tab='overview'}}}if(route==='projects'&&params.week)ui.projectOpen=params.week;if(params.lab)ui.lab=params.lab;ui.route=route;document.title=`${pageTitle()} — FORM / AI`;document.getElementById('sidebar').classList.remove('open');document.getElementById('overlay').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('hashchange',applyRoute);
function renderDashboard(){const a=countDone(), p=countProjectDone(), m=minutesAll(), next=coach();const activeDates=new Set(ALL_DAYS.map(d=>dayState(d.id).completedAt?.slice(0,10)).filter(Boolean));const last14=Array.from({length:14},(_,i)=>{const dt=new Date();dt.setDate(dt.getDate()-13+i);const key=[dt.getFullYear(),String(dt.getMonth()+1).padStart(2,'0'),String(dt.getDate()).padStart(2,'0')].join('-');return{day:dt.getDate(),key,active:activeDates.has(key)}});
return `${pageHead('Your workspace','Build the knowledge. Run the experiment.','A complete AI learning studio, from Python fundamentals to continual-learning research.',`<button class="btn" data-action="export">${I('download')} Export progress</button>`)}
<section class="hero"><div class="hero-inner"><div class="hero-kicker">YOUR PERSONAL RESEARCH JOURNEY</div><h2>From understanding models<br>to evolving them.</h2><p>63 focused lessons across eight core weeks, plus an optional research capstone. Your progress stays on this device.</p><button class="btn" style="margin-top:15px" data-action="open-day" data-day="${next.day.id}" data-tab="${next.tab}">${I('arrow-up-right')} Continue learning</button></div><div class="hero-right"><div class="hero-stat">${percent(a,63)}<small>%</small></div><div class="tiny" style="color:#aaa;margin-top:5px">LESSONS COMPLETE</div></div></section>
<section class="stat-grid">
${[['book-open','Lessons completed',`${a} / 63`,'Theory, practice and quiz'],['folder-check','Weekly projects',`${p} / 9`,'Milestone checklists'],['timer','Study time',`${m} min`,'Logged locally'],['flask-conical','Labs explored',`${LABS.filter(l=>state.labs[l.id]).length} / 6`,'Interactive simulations']].map(x=>`<div class="card stat-card"><div class="flex items-center between"><span class="upper">${x[1]}</span><span class="stat-icon">${I(x[0])}</span></div><div class="stat-number">${x[2]}</div><div class="tiny muted">${x[3]}</div></div>`).join('')}
</section>
<div class="grid-two"><section class="card padded"><div class="section-head"><h2 class="h2">Learning progress</h2><span class="tag">Real progress · by week</span></div><div class="chart-box"><canvas id="progressChart" aria-label="Number of lessons completed by week"></canvas><div id="progressChartFallback" hidden></div></div><div class="flex between tiny muted" style="margin-top:12px"><span>Completed daily lessons</span><a class="inline-link" href="#" data-action="nav" data-route="analytics">Detailed analytics ↗</a></div></section>
<section class="card padded"><div class="section-head"><h2 class="h2">Your study coach</h2><span class="tag">Rule-based · local</span></div><div class="upper" style="margin:16px 0 9px">${E(next.label)}</div><h3 style="font-size:21px;letter-spacing:-.5px;margin:0 0 8px">${E(next.title)}</h3><p class="muted">${E(next.text)}</p><div class="divider"></div><div class="flex gap-2 flex-wrap"><button class="btn btn-primary" data-action="open-day" data-day="${next.day.id}" data-tab="${next.tab}">${I('arrow-right')} Open lesson</button><button class="btn" data-action="nav" data-route="roadmap">${I('map')} Roadmap</button></div><p class="tiny muted" style="margin-top:16px">Recommendations use your marked lessons, practice steps, and quiz results—not an external AI service.</p></section></div>
<div class="section-head section"><h2 class="h2">Your nine-week map</h2><button class="btn btn-sm" data-action="nav" data-route="roadmap">Explore curriculum ${I('arrow-right')}</button></div>
<div class="week-grid">${WEEKS.map(w=>`<div class="card week-card"><div class="flex between items-center"><span class="week-number">WEEK ${String(w.number).padStart(2,'0')}</span><span class="tag ${w.core?'':'outline'}">${w.core?'Core':'Optional'}</span></div><h3 class="h3">${E(w.title)}</h3><p class="tiny muted" style="margin:0;min-height:32px">${E(w.subtitle)}</p>${progressBar(weekDone(w.number),7)}<div class="flex between items-center tiny"><span class="muted">${weekDone(w.number)} / 7 lessons</span><button class="btn btn-sm" data-action="open-week" data-week="${w.number}">Open ${I('arrow-right')}</button></div></div>`).join('')}</div>
<div class="grid-two section"><section class="card padded"><div class="section-head"><h2 class="h2">Recent study activity</h2><span class="upper">Last 14 days</span></div><div class="activity-calendar">${last14.map(day=>`<div title="${E(day.key)}${day.active?' · completed a lesson':''}" class="activity-cell ${day.active?'active':''}">${day.day}</div>`).join('')}</div><div class="divider"></div><p class="sm muted">Dark cells indicate dates on which at least one lesson was fully completed. This is based on saved timestamps, not browsing activity.</p></section><section class="card padded"><div class="section-head"><h2 class="h2">How it works</h2></div><div class="step-row" style="margin:14px 0"><div class="number-dot">1</div><div><div class="strong">Learn one concept</div><div class="tiny muted">Read the explanation and mark learned.</div></div></div><div class="step-row" style="margin:14px 0"><div class="number-dot">2</div><div><div class="strong">Practice with code</div><div class="tiny muted">Follow the guided steps and try the snippet.</div></div></div><div class="step-row" style="margin:14px 0"><div class="number-dot">3</div><div><div class="strong">Pass the check</div><div class="tiny muted">Complete the quiz to mark the lesson done.</div></div></div></section></div>`}
function renderRoadmap(){return `${pageHead('Learning path','Curriculum & milestones','Follow 56 core daily lessons, then complete the optional 7-day independent research capstone.',`<button class="btn" data-action="open-day" data-day="${nextLesson().id}">${I('play')} Resume learning</button>`)}
<section class="card padded" style="margin-bottom:18px"><h2 class="h2" style="margin-bottom:8px">The model-evolution lifecycle</h2><p class="sm muted">Select any stage to see how it fits your eventual research platform.</p><div class="flowchart">${FLOW.map((n,idx)=>`${idx?'<div class="flow-arrow">→</div>':''}<button data-action="flow" data-id="${n[0]}" class="flow-node ${ui.flow===n[0]?'active':''}">${E(n[1])}</button>`).join('')}</div><div class="flow-detail"><b>${E(FLOW.find(n=>n[0]===ui.flow)?.[1])}:</b> ${E(FLOW.find(n=>n[0]===ui.flow)?.[2])}</div></section>
<div class="flex between items-center" style="margin:20px 0"><div class="upper">Click a week to expand all daily lessons</div><span class="tag">${countDone()} of 63 complete</span></div>
${WEEKS.map(w=>`<details class="card week-accordion" ${ui.week===w.number?'open':''}><summary><div class="flex items-center gap-3"><div class="number-dot" style="width:42px;height:42px">${String(w.number).padStart(2,'0')}</div><div><div class="h3">${E(w.title)}</div><div class="tiny muted">${E(w.subtitle)}</div></div></div><div class="flex items-center gap-3"><span class="tag">${w.core?'Core':'Optional'}</span><span class="sm muted">${weekDone(w.number)} / 7</span>${I('chevron-down')}</div></summary><div class="accordion-content">${progressBar(weekDone(w.number),7)}<div class="day-grid" style="margin-top:15px">${w.days.map(d=>`<button class="day-tile ${done(d.id)?'done':''}" data-action="open-day" data-day="${d.id}"><div class="flex between items-center"><span class="upper">D${d.number}</span>${done(d.id)?I('check-circle-2'):I('circle')}</div><h4>${E(d.title)}</h4><span class="tiny muted" style="margin-top:auto">${status(d.id)}</span></button>`).join('')}</div><div class="soft-card" style="margin-top:14px"><div class="flex between items-center gap-3 flex-wrap"><div><div class="upper">Weekly project</div><div class="strong">${E(w.project)}</div><div class="tiny muted">${E(w.deliverable)}</div></div><button class="btn btn-sm" data-action="open-project" data-week="${w.number}">${I('folder')} View project</button></div></div></div></details>`).join('')}`}
/* ---- Custom CSS/JS dropdown (no native <select> UI) ---- */
const CLOSE_DD=()=>document.querySelectorAll('.dd.open').forEach(d=>d.classList.remove('open'));
function dropdown(id,value,options){const cur=options.find(o=>String(o[0])===String(value));return `<div class="dd" data-dd><button type="button" class="dd-btn" data-action="dd-toggle" aria-haspopup="listbox" aria-expanded="false"><span class="dd-label">${E(cur?cur[1]:value)}</span><span class="dd-chev">${I('chevron-down')}</span></button><div class="dd-menu" role="listbox" aria-label="${E(cur?cur[1]:'Choose an option')}">${options.map(o=>`<button type="button" class="dd-opt" role="option" aria-selected="${String(o[0])===String(value)}" data-action="dd-pick" data-dd="${E(id)}" data-value="${E(String(o[0]))}"><span class="dd-label">${E(o[1])}</span><span class="dd-check">${String(o[0])===String(value)?'✓':''}</span></button>`).join('')}</div></div>`}
function weekSelect(selected,kind='learnweek'){return dropdown(kind,selected,WEEKS.map(w=>[w.number,`Week ${w.number} — ${w.title}`]))}
function renderLearn(){const d=ALL_DAYS.find(x=>x.id===ui.day)||ALL_DAYS[0],s=dayState(d.id),w=WEEKS[d.week-1],parts=dayParts(d.id);ui.week=d.week;
const tabs=[['overview','Overview'],['practice','Practice & code'],['quiz','Knowledge check'],['resources','References'],['notes','Notes']];const flags=[['Concept learned',parts[0]],['Practice verified',parts[1]],['Quiz passed',parts[2]]];
return `${pageHead('Daily guided learning','One concept at a time','Read, practice, check understanding, and save your work locally.',`<button class="btn" data-action="open-day" data-day="${nextLesson().id}">${I('crosshair')} Next incomplete</button>`)}
<div class="learn-layout"><aside class="card padded" style="position:relative"><div class="upper" style="margin-bottom:8px">Jump to week</div>${weekSelect(d.week)}<div class="divider"></div><div class="flex between items-center" style="margin:0 0 6px"><span class="upper">Week ${d.week} lessons</span><span class="tiny muted">${weekDone(d.week)}/7</span></div><div class="lesson-list">${w.days.map(x=>`<button data-action="open-day" data-day="${x.id}" class="day-item ${x.id===d.id?'active':''} ${done(x.id)?'done':''}"><span class="day-counter">${done(x.id)?'✓':x.dayInWeek}</span><span style="min-width:0"><span class="tiny muted">Day ${x.number}</span><span style="display:block;font-size:12px;font-weight:700;line-height:1.35">${E(x.title)}</span></span></button>`).join('')}</div></aside>
<article class="card" style="min-width:0"><div class="padded" style="padding-bottom:18px"><div class="flex between items-center gap-2 flex-wrap"><div class="pill-row"><span class="tag">W${d.week} / D${d.number}</span><span class="tag outline">${E(w.theme)}</span><span class="tag outline">${d.duration} min suggested</span></div><button class="btn btn-icon btn-sm" data-action="bookmark" data-day="${d.id}" title="Bookmark lesson" aria-label="Bookmark lesson">${I(s.bookmarked?'bookmark-check':'bookmark')}</button></div><h2 class="lesson-title">${E(d.title)}</h2><p class="muted" style="margin:0 0 16px">${E(d.explanation)}</p><div class="pill-row">${flags.map(x=>`<span class="tag ${x[1]?'dark':'outline'}">${x[1]?'✓':'○'} ${E(x[0])}</span>`).join('')}</div></div>
<div class="tabs" role="tablist">${tabs.map(t=>`<button class="tab ${ui.tab===t[0]?'active':''}" data-action="lesson-tab" data-tab="${t[0]}" role="tab" aria-selected="${ui.tab===t[0]}">${E(t[1])}</button>`).join('')}</div>
<div class="tab-content">${renderLessonTab(d)}</div>
<div class="padded" style="padding-top:0;display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap"><button class="btn" data-action="prev-day" data-day="${d.id}" ${d.number===1?'disabled':''}>${I('arrow-left')} Previous day</button><button class="btn btn-primary" data-action="next-day" data-day="${d.id}" ${d.number===63?'disabled':''}>Next day ${I('arrow-right')}</button></div>
</article></div>`}
function renderLessonTab(d){const s=dayState(d.id),w=WEEKS[d.week-1];if(ui.tab==='overview')return`<div class="upper">Concept explanation</div><div class="lesson-main"><h3 class="h3">What you'll learn</h3><p>${E(d.explanation)}</p></div><div class="step-row" style="margin:18px 0"><div class="number-dot">01</div><div><div class="strong">Understand the intuition</div><p class="sm muted">Read the explanation and identify the inputs, operation and outputs. Explain the concept out loud without looking at the answer.</p></div></div><div class="step-row" style="margin:18px 0"><div class="number-dot">02</div><div><div class="strong">Connect it to model longevity</div><p class="sm muted">Ask how ${E(d.title.toLowerCase())} could affect a model's capability, training cost, inference correctness or knowledge retention.</p></div></div><div class="step-row" style="margin:18px 0"><div class="number-dot">03</div><div><div class="strong">Prove understanding in practice</div><p class="sm muted">Your task today: ${E(d.practice)}</p></div></div><div class="divider"></div><label class="checkline"><input type="checkbox" data-action="learned" data-day="${d.id}" ${s.learned?'checked':''}><span><span class="strong">I can explain this concept without notes</span><br><span class="tiny muted">Mark this only after the explanation makes sense.</span></span></label><div class="flex gap-2 flex-wrap" style="margin-top:20px"><button class="btn btn-primary" data-action="lesson-tab" data-tab="practice">Practice with code ${I('arrow-right')}</button><button class="btn" data-action="add-minutes" data-day="${d.id}" data-minutes="15">${I('clock')} Log 15 min</button></div>`;
if(ui.tab==='practice'){const code=SNIPPETS[d.id]||'# Complete the exercise in your local Python environment.';const steps=[`Implement: ${d.practice}`,`Run or inspect the example, change at least one input, and compare the observed output with your prediction.`,`Record the result, any errors, and one limitation in your lesson notes.`];return `<div class="flex between items-center"><h3 class="h3">Guided hands-on exercise</h3><span class="tag">${s.steps.filter(Boolean).length} / 3 checks</span></div><p class="sm muted" style="margin:9px 0 18px">Open a Python environment or notebook. The snippets here are copyable examples—not executed in this browser.</p><div class="lesson-steps">${steps.map((step,i)=>`<label class="step-card checkline"><input type="checkbox" data-action="practice-step" data-day="${d.id}" data-index="${i}" ${s.steps[i]?'checked':''}><span><b class="sm">Step ${i+1}</b><br><span class="sm muted">${E(step)}</span></span></label>`).join('')}</div><div class="section-head" style="margin-top:20px"><h3 class="h3">Copyable starting code</h3><span class="tag">Python / shell</span></div><div class="codebox"><div class="codehead"><span>lesson_${d.number}.py · example</span><button class="btn btn-sm" data-action="copy-code" data-day="${d.id}">${I('copy')} Copy code</button></div><pre><code>${E(code)}</code></pre></div><p class="tiny muted" style="margin:12px 0">Dependencies depend on the lesson. Check the official reference cards. GPU examples are optional and may require separate Python packages or model downloads.</p><div class="flex gap-2 flex-wrap"><button class="btn btn-primary" data-action="lesson-tab" data-tab="quiz">Open knowledge check ${I('arrow-right')}</button><button class="btn" data-action="lesson-tab" data-tab="notes">${I('notebook-pen')} Record observations</button></div>`}
if(ui.tab==='quiz'){return `<div class="upper">Day ${d.number} · Knowledge check</div><h3 style="font-size:19px;margin:10px 0 16px;letter-spacing:-.4px">${E(d.quiz)}</h3><div>${d.options.map((o,i)=>`<button class="quiz-option ${s.choice===i?'picked':''} ${s.quizPassed&&i===d.correct?'correct':''}" data-action="answer" data-day="${d.id}" data-choice="${i}"><span class="option-letter">${'ABC'[i]}</span><span>${E(o)}</span>${s.quizPassed&&i===d.correct?I('check-circle-2'):''}</button>`).join('')}</div>${s.choice!==null?`<div class="message" style="margin-top:14px"><strong>${s.quizPassed?'Correct — checkpoint passed':'Not quite — review and retry'}</strong>${E(s.quizPassed?d.explanationAnswer:'Think about the key concept above, then select a different answer. You can also return to the Overview tab.')}${s.wrong&&!s.quizPassed?` <span class="tiny muted">Attempts needing review: ${s.wrong}</span>`:''}</div>`:`<p class="tiny muted">Select an answer to receive immediate feedback. A correct answer completes this checkpoint.</p>`}<div class="flex flex-wrap gap-2" style="margin-top:20px"><button class="btn" data-action="lesson-tab" data-tab="overview">${I('book-open')} Revisit explanation</button><button class="btn btn-primary" data-action="lesson-tab" data-tab="notes">Write a reflection ${I('arrow-right')}</button></div>`}
if(ui.tab==='resources')return`<h3 class="h3">Curated official references</h3><p class="sm muted">Read the source material and compare its examples with the exercises in this week.</p><div style="display:grid;gap:10px;margin-top:17px">${w.resources.map((r,idx)=>`<div class="card padded flex items-center between gap-3"><div><span class="upper">Reference ${idx+1}</span><div class="strong">${E(r[0])}</div><p class="tiny muted" style="margin:3px 0">${E(new URL(r[1]).hostname)}</p></div><a class="btn btn-sm" target="_blank" rel="noopener noreferrer" href="${E(r[1])}">${I('external-link')} Open</a></div>`).join('')}</div>`;
if(ui.tab==='notes')return`<h3 class="h3">Private learning notes</h3><p class="sm muted">Write down your understanding, mistakes and experiment outputs. These notes remain in your local browser and are included in exported backups.</p><textarea class="textarea" rows="10" data-input="note" data-day="${d.id}" maxlength="12000" placeholder="What did I learn? What surprised me? What experiment should I run next?">${E(s.notes)}</textarea><div class="flex between items-center" style="margin-top:10px"><span class="tiny muted">Autosaved to ${E(storageMode)}</span><button class="btn btn-sm" data-action="add-minutes" data-day="${d.id}" data-minutes="25">${I('clock')} Log 25 min of study</button></div>`;
return ''}
function labVal(key,fallback){const v=state.labValues?.[key];return v===undefined?fallback:v}
function labInput(key,label,defaultVal,min,max,step=1){return `<div class="control"><label for="lab-${key}"><span>${E(label)}</span><span class="tag" id="v-${key}">${E(labVal(key,defaultVal))}</span></label><input id="lab-${key}" type="range" min="${min}" max="${max}" step="${step}" data-input="lab" data-key="${key}" value="${E(labVal(key,defaultVal))}"></div>`}
function renderLabs(){const lab=LABS.find(l=>l.id===ui.lab)||LABS[0];const inspected=LABS.filter(x=>state.labs[x.id]).length;
let controls='';
if(lab.id==='tensor')controls=`<div class="upper">Define tensor dimensions</div><p class="sm muted">Enter comma-separated positive dimensions, up to four axes. Calculations assume float32 elements.</p><input class="field" data-input="lab" data-key="tensorDims" value="${E(labVal('tensorDims','4, 2, 3'))}" aria-label="Tensor dimensions" placeholder="4, 2, 3"><p class="tiny muted" style="margin-top:10px">Try <code>32, 10</code>, <code>4, 2, 3</code>, and <code>2, 3, 224, 224</code>.</p>`;
if(lab.id==='gradient')controls=`<p class="sm muted">A toy one-parameter model starts at w=0 and minimizes L(w)=2(w−2)². Observe convergence as the learning rate changes.</p>${labInput('gradLR','Learning rate',0.1,0.05,0.65,0.05)}${labInput('gradSteps','Training iterations',12,0,30,1)}`;
if(lab.id==='tokenizer')controls=`<p class="sm muted">A local demonstration of three segmentation strategies. The "toy subword" option is <b>not</b> a learned BPE tokenizer.</p><textarea class="textarea" data-input="lab" data-key="tokenText" rows="3" placeholder="Enter text">${E(labVal('tokenText','Training older models with new knowledge'))}</textarea><div style="margin-top:14px"><label class="upper" id="tokenModeLabel">Segmentation strategy</label>${dropdown('tokenmode',labVal('tokenMode','words'),[['words','Whitespace-separated words'],['chars','Unicode characters'],['toy','Toy 3-character chunks']])}</div>`;
if(lab.id==='attention')controls=`<p class="sm muted">For one query, adjust three similarity scores. Softmax maps scores to nonnegative weights summing to 1. The value vectors are illustrative scalars [2, 0, −1].</p>${labInput('a1','Token 1 score',1,-3,3,.25)}${labInput('a2','Token 2 score',0,-3,3,.25)}${labInput('a3','Token 3 score',-1,-3,3,.25)}`;
if(lab.id==='lora')controls=`<p class="sm muted">Compare parameters in one dense matrix (output × input) against a LoRA update with two low-rank matrices of size (output × rank) and (rank × input). This excludes other model weights and optimizer state.</p>${labInput('loraIn','Input width',512,128,8192,128)}${labInput('loraOut','Output width',512,128,8192,128)}${labInput('loraRank','Adapter rank',8,1,64,1)}`;
if(lab.id==='forgetting')controls=`<p class="sm muted">Adjust four evaluation scores. These are illustrative inputs—not measured model performance. Forgetting = old-task accuracy before − after. New gain = new-task accuracy after − before.</p>${labInput('oldBefore','Old-task before (%)',85,0,100,1)}${labInput('oldAfter','Old-task after (%)',72,0,100,1)}${labInput('newBefore','New-task before (%)',35,0,100,1)}${labInput('newAfter','New-task after (%)',73,0,100,1)}`;
return `${pageHead('Hands-on learning','Interactive concept labs','Explore the mathematics in your browser. These JavaScript simulations are separate from the copyable Python exercises.',`<span class="tag">${inspected} / ${LABS.length} labs marked practiced</span>`)}<div class="lab-list">${LABS.map(l=>`<button class="lab-tab ${l.id===lab.id?'active':''}" data-action="lab-select" data-lab="${l.id}">${I(l.icon)} ${E(l.title)} ${state.labs[l.id]?'✓':''}</button>`).join('')}</div>
<div class="grid-two" style="grid-template-columns:1fr 1.05fr"><div class="card padded"><div class="flex between items-center gap-2"><span class="tag">Week ${lab.week}</span><span class="tag outline">No backend · live JS</span></div><h2 class="h2" style="margin:14px 0 7px">${E(lab.title)}</h2><p class="sm muted" style="margin-top:0;margin-bottom:22px">${E(lab.desc)}</p>${controls}<div class="divider"></div><label class="checkline"><input type="checkbox" data-action="lab-done" data-lab="${lab.id}" ${state.labs[lab.id]?'checked':''}><span><b>Mark lab practiced</b><br><span class="tiny muted">Try at least three configurations and be able to explain the outputs.</span></span></label></div><div class="card padded"><div class="section-head"><h2 class="h2">Live results</h2><span class="tag">Calculated locally</span></div><div id="labOutput"></div></div></div>`}
function svgLine(series,opts={}){const width=560,height=205,pad={l:48,r:12,t:12,b:31};let pts=series.flatMap(s=>s.values.map(v=>v[1])).filter(Number.isFinite);if(!pts.length)pts=[0,1];let ymin=opts.ymin??Math.min(0,...pts),ymax=opts.ymax??Math.max(...pts);if(ymax-ymin<1e-9)ymax=ymin+1;
const nmax=Math.max(1,...series.map(s=>s.values.length-1));const xx=x=>pad.l+x/nmax*(width-pad.l-pad.r), yy=y=>pad.t+(1-(y-ymin)/(ymax-ymin))*(height-pad.t-pad.b);
const axes=Array.from({length:5},(_,k)=>{const value=ymin+(ymax-ymin)*k/4,y=yy(value);return `<line x1="${pad.l}" y1="${y}" x2="${width-pad.r}" y2="${y}" stroke="var(--line)"/><text x="${pad.l-7}" y="${y+4}" text-anchor="end">${Math.abs(value)>999?value.toExponential(1):Number(value.toFixed(2))}</text>`}).join('');
const paths=series.map((s,i)=>`<path d="${s.values.map((pair,j)=>`${j?'L':'M'}${xx(j).toFixed(2)},${yy(pair[1]).toFixed(2)}`).join(' ')}" fill="none" stroke="${i?'#999':'var(--primary)'}" stroke-width="${i?2:2.8}" stroke-linecap="round"/>`).join('');
return `<svg class="svg-plot" viewBox="0 0 ${width} ${height}" role="img" aria-label="${E(opts.label||'Line chart')}">${axes}${paths}<text x="${pad.l}" y="${height-6}">0</text><text x="${width-pad.r}" y="${height-6}" text-anchor="end">${nmax} iterations</text></svg>`}
function compareBars(items){return `<div class="bar-compare">${items.map(([name,value,max=100])=>`<div><div class="bar-label"><span>${E(name)}</span><b>${Number(value).toFixed(2)}${max===100?'%':''}</b></div><div class="bar-bg"><div class="bar-fg" style="width:${Math.max(0,Math.min(100,100*value/max))}%"></div></div></div>`).join('')}</div>`}
function updateLabOutput(){if(ui.route!=='labs')return;const target=document.getElementById('labOutput');if(!target)return;const get=(key,defaultVal)=>labVal(key,defaultVal);let html='';
if(ui.lab==='tensor'){const raw=String(get('tensorDims','4, 2, 3'));const dims=raw.split(',').map(v=>Number(v.trim()));if(!dims.length||dims.length>4||dims.some(v=>!Number.isInteger(v)||v<1||v>20000)||dims.reduce((a,b)=>a*b,1)>1e9){html='<div class="message">Enter 1–4 positive whole-number dimensions with at most one billion elements.</div>'}else{const count=dims.reduce((a,b)=>a*b,1);html=`<div class="metric-grid"><div class="metric-box"><div class="upper">Rank</div><div class="value">${dims.length}D</div></div><div class="metric-box"><div class="upper">Elements</div><div class="value">${fmt(count)}</div></div><div class="metric-box"><div class="upper">Float32 data</div><div class="value">${(count*4/1024/1024).toFixed(2)} MiB</div></div></div><div class="soft-card" style="margin-top:15px"><div class="upper">Shape</div><h2 class="h2" style="margin:8px 0">(${dims.join(', ')})</h2><p class="sm muted">${dims.length===1?'One axis: a vector.':dims.length===2?'Two axes: a matrix.':dims.length===3?'Three axes: often batch × sequence × features.':'Four axes: often batch × channels × height × width.'} Raw float32 data uses 4 bytes per element, excluding metadata.</p></div><div class="pill-row" style="margin-top:13px">${dims.map((n,i)=>`<span class="token-chip">Axis ${i}: ${fmt(n)}</span>`).join('')}</div>`}}
if(ui.lab==='gradient'){const lr=Number(get('gradLR',.1)),steps=Number(get('gradSteps',12));const vals=Array.from({length:steps+1},(_,k)=>{const w=2*(1-Math.pow(1-4*lr,k));return[k,2*(w-2)**2]});const learned=2*(1-Math.pow(1-4*lr,steps));const loss=vals.at(-1)[1];const behavior=lr<.25?'Monotonic convergence toward the minimum.':lr===.25?'Exact optimum in one step for this toy quadratic.':lr<.5?'Oscillating convergence: overshoots shrink over time.':lr===.5?'Non-convergent oscillation: it alternates between two weights.':'Divergence: overshoot magnitudes grow every step.';html=`<div class="metric-grid"><div class="metric-box"><div class="upper">Learned w</div><div class="value">${Math.abs(learned)>999?learned.toExponential(2):learned.toFixed(3)}</div></div><div class="metric-box"><div class="upper">Target w</div><div class="value">2.00</div></div><div class="metric-box"><div class="upper">Final MSE</div><div class="value">${loss>1000||loss<.001?loss.toExponential(2):loss.toFixed(3)}</div></div></div><div style="margin:20px 0"><div class="upper">Loss curve across updates</div>${svgLine([{values:vals}],{label:'Squared-error loss across gradient descent updates'})}</div><div class="message"><strong>Interpretation</strong>${behavior}</div>`}
if(ui.lab==='tokenizer'){const str=String(get('tokenText','Training older models with new knowledge')).slice(0,500);const mode=get('tokenMode','words');let tokens=mode==='chars'?Array.from(str):mode==='toy'?str.split(/(\s+)/).filter(x=>x.length).flatMap(x=>/^\s+$/.test(x)?[x]:Array.from({length:Math.ceil(x.length/3)},(_,i)=>x.slice(i*3,i*3+3))):str.trim().split(/\s+/).filter(Boolean);html=`<div class="metric-grid"><div class="metric-box"><div class="upper">Characters</div><div class="value">${Array.from(str).length}</div></div><div class="metric-box"><div class="upper">Segments</div><div class="value">${tokens.length}</div></div><div class="metric-box"><div class="upper">Method</div><div class="value" style="font-size:17px">${mode==='chars'?'Chars':mode==='toy'?'Toy chunks':'Words'}</div></div></div><div class="upper" style="margin:17px 0 10px">Preview (first 75 segments)</div><div class="pill-row">${tokens.slice(0,75).map((t,i)=>`<span class="token-chip" title="Segment ${i+1}">${E(t===' '?'␠':t==='\n'?'↵':t)}</span>`).join('')||'<span class="muted">Type text to explore.</span>'}</div>${tokens.length>75?'<p class="tiny muted">Additional tokens hidden for readability.</p>':''}<div class="message" style="margin-top:20px"><strong>Important distinction</strong>This is a conceptual segmentation exercise. Real LLM token IDs are determined by a trained tokenizer with a fixed vocabulary, often based on subword algorithms.</div>`}
if(ui.lab==='attention'){const scores=['a1','a2','a3'].map((k,i)=>Number(get(k,[1,0,-1][i])));const mm=Math.max(...scores);const exp=scores.map(x=>Math.exp(x-mm)),sum=exp.reduce((a,b)=>a+b,0),probs=exp.map(x=>x/sum);const weighted=probs[0]*2+probs[1]*0-probs[2];html=`<div class="metric-grid"><div class="metric-box"><div class="upper">Weight sum</div><div class="value">${probs.reduce((a,b)=>a+b,0).toFixed(3)}</div></div><div class="metric-box"><div class="upper">Weighted value</div><div class="value">${weighted.toFixed(3)}</div></div><div class="metric-box"><div class="upper">Top token</div><div class="value">${probs.indexOf(Math.max(...probs))+1}</div></div></div><div class="upper" style="margin:20px 0 10px">Attention distribution</div>${compareBars(probs.map((p,i)=>[`Token ${i+1} · score ${scores[i]}`,p*100]))}<div class="message" style="margin-top:20px"><strong>What this means</strong>Increasing one score increases its relative softmax weight. The final output is a weighted combination of value vectors. Real attention uses learned query, key and value matrices.</div>`}
if(ui.lab==='lora'){const n=Number(get('loraIn',512)),m=Number(get('loraOut',512)),r=Number(get('loraRank',8));const full=n*m,adp=r*(n+m),pct=100*adp/full;html=`<div class="metric-grid"><div class="metric-box"><div class="upper">Full matrix</div><div class="value">${fmt(full)}</div></div><div class="metric-box"><div class="upper">LoRA matrices</div><div class="value">${fmt(adp)}</div></div><div class="metric-box"><div class="upper">Reduction</div><div class="value">${(100-pct).toFixed(1)}%</div></div></div><div class="upper" style="margin:21px 0 10px">Parameter comparison</div>${compareBars([['Full matrix',full,full],['LoRA update',adp,full]])}<div class="message" style="margin-top:20px"><strong>How to interpret</strong>LoRA learns A and B matrices (r × input and output × r), not the full pretrained matrix. At high rank it may not save parameters; this example counts one matrix only, not a whole model or its activation memory.</div>`}
if(ui.lab==='forgetting'){const o0=Number(get('oldBefore',85)),o1=Number(get('oldAfter',72)),n0=Number(get('newBefore',35)),n1=Number(get('newAfter',73));html=`<div class="metric-grid"><div class="metric-box"><div class="upper">Old-task drop</div><div class="value">${(o0-o1).toFixed(0)} pp</div></div><div class="metric-box"><div class="upper">New-task gain</div><div class="value">${(n1-n0).toFixed(0)} pp</div></div><div class="metric-box"><div class="upper">Retention ratio</div><div class="value">${o0?(100*o1/o0).toFixed(1)+'%':'N/A'}</div></div></div><div class="upper" style="margin:20px 0 10px">Before vs after scores</div>${compareBars([['Old before',o0],['Old after',o1],['New before',n0],['New after',n1]])}<div class="message" style="margin-top:20px"><strong>Research interpretation</strong>${o1<o0?`Old-task accuracy dropped by ${o0-o1} percentage points. This is an observed-style forgetting metric for the selected demo values.`:o1===o0?'Old-task score is unchanged.':'Old-task score improved after the update.'} ${n1>n0?'New-task score improved.':n1<n0?'New-task score declined.':'New-task score stayed unchanged.'} Real conclusions need controlled held-out tests and uncertainty estimates.</div>`}
target.innerHTML=html}
