function renderSettings(){return`${pageHead('Preferences','Settings, privacy & backup','Your learning data belongs to you. Manage the storage, portable export and theme here.')}
<div class="grid-two"><section class="card padded"><div class="section-head"><h2 class="h2">Local data</h2>${I('database')}</div><div class="soft-card"><span class="upper">Current persistence mode</span><div class="h3" style="margin:7px 0">${E(storageMode)}</div><p class="tiny muted">IndexedDB is preferred. If your browser disallows it on a local file, the application attempts localStorage. Memory-only mode requires manual export before closing.</p></div><div class="divider"></div><h3 class="h3">Export your learning record</h3><p class="sm muted">Download a JSON containing lesson checkmarks, quiz answers, notes, lab status, project checklists, and logged minutes. No model weights or external repositories are included.</p><div class="flex gap-2 flex-wrap"><button class="btn btn-primary" data-action="export">${I('download')} Export JSON backup</button><button class="btn" data-action="import">${I('upload')} Restore JSON backup</button></div><div class="divider"></div><h3 class="h3">Reset all progress</h3><p class="sm muted">Remove your locally stored notes, completions and project progress. Export first if you may need this information again.</p><button class="btn" data-action="reset">${I('trash-2')} Reset learning data</button></section>
<section class="card padded"><div class="section-head"><h2 class="h2">Focus timer & sound</h2>${I('timer')}</div><p class="sm muted">Set the default focus block. It runs in the top bar, and each completed session is logged as study minutes on the open lesson.</p><div class="stepper" style="margin:16px 0 14px"><button class="btn btn-icon" data-action="timer-duration" data-delta="-5" aria-label="Decrease focus time by 5 minutes">${I('minus')}</button><span class="val" id="timerMinutes">${state.settings.focusMinutes} min</span><button class="btn btn-icon" data-action="timer-duration" data-delta="5" aria-label="Increase focus time by 5 minutes">${I('plus')}</button><span class="tiny muted">±5 min steps · 1–120 min</span></div><div><label class="upper" style="display:block;margin-bottom:7px">Quick presets</label>${dropdown('timerpreset',state.settings.focusMinutes,[[10,'10 minutes'],[15,'15 minutes'],[25,'25 minutes · classic Pomodoro'],[45,'45 minutes'],[60,'60 minutes'],[90,'90 minutes deep block']])}</div><div class="divider"></div><h3 class="h3">Completion beep</h3><p class="sm muted">Play a short beep when a focus session finishes. It is generated in the browser with the Web Audio API — no audio file, no network request.</p><div class="flex gap-2 flex-wrap" style="margin-top:10px"><button class="btn ${state.settings.sound!==false?'btn-primary':''}" data-action="beep-toggle">${state.settings.sound!==false?`${I('volume-2')} Beep on`:`${I('volume-x')} Beep off`}</button><button class="btn" data-action="test-beep">Test beep</button></div></section>
<section class="card padded"><div class="section-head"><h2 class="h2">Appearance & access</h2>${I('sliders-horizontal')}</div><p class="sm muted">Slate shades in light, its deep mirror in dark, with a single mauve accent guiding active states, progress and quizzes.</p><div class="flex gap-2"><button class="btn ${state.theme==='light'?'btn-primary':''}" data-action="set-theme" data-theme="light">${I('sun')} Light · Slate + mauve</button><button class="btn ${state.theme==='dark'?'btn-primary':''}" data-action="set-theme" data-theme="dark">${I('moon')} Dark · Slate + mauve</button></div><div class="divider"></div><h3 class="h3">Architecture</h3><div class="pill-row">${['Vanilla HTML','Custom CSS + optional Tailwind CDN','Vanilla JavaScript','IndexedDB','Optional Lucide icons','Optional Chart.js'].map(x=>`<span class="tag outline">${E(x)}</span>`).join('')}</div><p class="sm muted" style="margin-top:16px">Core features, including the offline SVG chart fallbacks, are implemented locally. The CDNs are used for optional styling, icons and chart enhancement only.</p><div class="divider"></div><h3 class="h3">Privacy & deployment</h3><p class="sm muted">No login, external database, data collection, embedded third-party chat, or remote execution endpoint. CDN access and outbound reference links still involve contacting external sites when online.</p><p class="tiny muted">For more reliable browser storage, serve this HTML with <code>python3 -m http.server 8000</code> and visit <code>http://localhost:8000</code>. Export backups before clearing browser site data.</p></section></div>`}
function svgBars(labels,values,max=7){const W=680,H=252,pad={left:22,right:8,top:12,bottom:34};const plotW=W-pad.left-pad.right,plotH=H-pad.top-pad.bottom,gap=16,bar=plotW/labels.length-gap;
return `<svg viewBox="0 0 ${W} ${H}" class="svg-plot" role="img" aria-label="Bar chart showing ${labels.length} weekly values">${[0,.25,.5,.75,1].map(q=>`<line x1="${pad.left}" y1="${pad.top+(1-q)*plotH}" x2="${W-pad.right}" y2="${pad.top+(1-q)*plotH}" stroke="var(--line)"/>`).join('')}${values.map((v,i)=>{const bh=max?Math.max(0,v/max*plotH):0,x=pad.left+i*(plotW/labels.length)+gap/2,y=pad.top+plotH-bh;return `<rect x="${x}" y="${y}" width="${bar}" height="${bh}" rx="3" fill="var(--primary)"/><text x="${x+bar/2}" y="${Math.max(12,y-6)}" text-anchor="middle" fill="var(--muted)" font-size="11">${v}</text><text x="${x+bar/2}" y="${H-8}" text-anchor="middle" fill="var(--muted)" font-size="11">${labels[i]}</text>`}).join('')}</svg>`}
let charts=[];
function drawProgressChart(){for(const c of charts){try{c.destroy()}catch{}}charts=[];const values=WEEKS.map(w=>weekDone(w.number)),mins=WEEKS.map(w=>w.days.reduce((n,d)=>n+(state.minutes[d.id]||0),0));const label=WEEKS.map(w=>'W'+w.number);function mount(id,data,max,labelText){const el=document.getElementById(id);if(!el)return;const alt=document.getElementById(id+'Fallback');if(window.Chart){const dark=state.theme==='dark',ink=dark?'#c193a8':'#8d5c6f',line=dark?'#334155':'#e2e8f0';const obj=new Chart(el,{type:'bar',data:{labels:label,datasets:[{label:labelText,data,backgroundColor:ink,borderRadius:5,maxBarThickness:30}]},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>`${c.parsed.y} ${labelText.toLowerCase()}`}}},scales:{x:{grid:{display:false},ticks:{color:dark?'#aaa':'#666'}},y:{beginAtZero:true,suggestedMax:max,grid:{color:line},ticks:{precision:0,color:dark?'#aaa':'#666'}}}}});charts.push(obj)}else{el.hidden=true;if(alt){alt.hidden=false;alt.innerHTML=svgBars(label,data,max)}}}
mount('progressChart',values,7,'Lessons complete');mount('timeChart',mins,Math.max(20,...mins),'Minutes logged')}
function setTheme(theme){state.theme=theme==='dark'?'dark':'light';applyTheme();save();render()}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('Code copied to clipboard');return}const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.left='-9999px';document.body.appendChild(field);field.focus();field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw new Error('copy not supported');toast('Code copied to clipboard')}catch(err){toast('Clipboard blocked. Select and copy the code manually.')}}
function exportState(){const data=JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2);const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='form-ai-progress-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Your progress backup is downloading')}
function advanceDay(id,delta){const day=ALL_DAYS.find(d=>d.id===id);if(!day)return;const n=day.number+delta;if(n>=1&&n<=63)navigate('learn',{day:'d'+n})}
let beepCtx=null;
function playBeep(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;beepCtx=beepCtx||new AC();if(beepCtx.state==='suspended')beepCtx.resume();const t=beepCtx.currentTime;[[0,880],[.22,880],[.44,1175]].forEach(([off,freq])=>{const o=beepCtx.createOscillator(),g=beepCtx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,t+off);g.gain.setValueAtTime(.0001,t+off);g.gain.exponentialRampToValueAtTime(.25,t+off+.02);g.gain.exponentialRampToValueAtTime(.0001,t+off+.18);o.connect(g).connect(beepCtx.destination);o.start(t+off);o.stop(t+off+.2)})}catch(e){console.warn('Beep unavailable:',e)}}
function applyTimerMinutes(mins){state.settings=state.settings||{sound:true};state.settings.focusMinutes=Math.min(120,Math.max(1,Math.round(Number(mins)||25)));if(!timer.running)timer.duration=timer.remaining=state.settings.focusMinutes*60;updateTimerUI()}
function focusToggle(){if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.deadline-Date.now())/1000));timer.running=false;toast('Focus timer paused')}else{timer.deadline=Date.now()+timer.remaining*1000;timer.day=ui.day;timer.running=true;toast(`${timer.duration/60}-minute focus session started`)}updateTimerUI()}
function focusReset(){timer.running=false;timer.duration=timer.remaining=(state.settings?.focusMinutes||25)*60;updateTimerUI();toast('Focus timer reset')}
function startTimerTicker(){timer.interval=setInterval(()=>{if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.deadline-Date.now())/1000));if(timer.remaining===0){timer.running=false;const day=timer.day||ui.day,mins=timer.duration/60;state.minutes[day]=(state.minutes[day]||0)+mins;save();if(state.settings.sound!==false)playBeep();toast(`Focus session complete. ${mins} minutes recorded.`);if(['dashboard','analytics','notebook'].includes(ui.route))render()}updateTimerUI()}},700)}
function updateTimerUI(){const mm=String(Math.floor(timer.remaining/60)).padStart(2,'0'),ss=String(timer.remaining%60).padStart(2,'0');const label=document.getElementById('timerLabel');const act=document.getElementById('timerAction');if(label)label.textContent=`${mm}:${ss}`;if(act)act.textContent=timer.running?'Pause':timer.remaining===timer.duration?'Focus':'Resume'}
function renderSearchResults(){const q=ui.search.toLowerCase().trim(),found=q?ALL_DAYS.filter(d=>(d.title+' '+d.explanation+' '+d.practice+' '+WEEKS[d.week-1].title).toLowerCase().includes(q)):[];return q?`${found.length?found.slice(0,40).map(d=>`<div class="search-result"><div><span class="upper">W${d.week} · DAY ${d.number}</span><div class="strong">${E(d.title)}</div><p class="sm muted" style="margin:4px 0">${E(d.explanation.slice(0,160))}</p></div><button class="btn btn-sm" data-action="open-day" data-day="${d.id}">Open ${I('arrow-right')}</button></div>`).join(''):`<div class="empty">No lessons match “${E(ui.search)}”. Try a broader term.</div>`}`:`<div class="empty">Try searching: <b>gradient</b>, <b>attention</b>, <b>LoRA</b>, <b>forgetting</b>, or <b>model registry</b>.</div>`}
function renderSearch(){return `${pageHead('Find knowledge','Search the curriculum','Find terms in all 63 daily lessons and their practice instructions. This search runs entirely in your browser.')}
<div class="card padded"><label class="upper" for="course-search">Search topics, concepts or tasks</label><input class="field" id="course-search" data-input="search" type="search" value="${E(ui.search)}" placeholder="e.g. gradient descent, tokenizer, LoRA" style="margin:12px 0" autocomplete="off"><div id="searchResults">${renderSearchResults()}</div></div>`}
NAV.splice(3,0,['search','Search lessons','search']);
function doClick(action,el){const id=el.dataset.day,week=Number(el.dataset.week);switch(action){
case 'toggle-sidebar':document.getElementById('sidebar').classList.toggle('open');document.getElementById('overlay').classList.toggle('open');break;
case 'nav':navigate(el.dataset.route);break;
case 'open-day':navigate('learn',{day:id,tab:el.dataset.tab||'overview'});break;
case 'open-week':navigate('learn',{week});break;
case 'open-project':navigate('projects',{week});break;
case 'flow':ui.flow=el.dataset.id;render();break;
case 'lesson-tab':{ui.tab=el.dataset.tab;try{history.replaceState(null,'',buildHash('learn',{day:ui.day,tab:ui.tab}))}catch(e){}render();break}
case 'dd-toggle':{const box=el.closest('[data-dd]');const wasOpen=box.classList.contains('open');CLOSE_DD();if(!wasOpen){box.classList.add('open');box.querySelector('.dd-opt')?.focus()}break}
case 'dd-pick':{const ddid=el.dataset.dd,value=el.dataset.value;CLOSE_DD();if(ddid==='learnweek')navigate('learn',{week:Number(value)});
 if(ddid==='resweek'){ui.week=Number(value);navigate('resources')}
 if(ddid==='tokenmode'){state.labValues.tokenMode=value;save();render()}
 if(ddid==='timerpreset'){applyTimerMinutes(Number(value));save();render()}break}
case 'timer-duration':{applyTimerMinutes(state.settings.focusMinutes+Number(el.dataset.delta||0));save();render();toast(`Focus block set to ${state.settings.focusMinutes} minutes`);break}
case 'beep-toggle':state.settings.sound=state.settings.sound===false?true:false;save();render();toast(state.settings.sound?'Completion beep enabled':'Completion beep disabled');break;
case 'test-beep':playBeep();toast('Beep test — this is what a completed session sounds like');break;
case 'bookmark':changeDay(id,s=>s.bookmarked=!s.bookmarked);break;
case 'prev-day':advanceDay(id,-1);break;
case 'next-day':advanceDay(id,1);break;
case 'answer':changeDay(id,s=>{const choice=Number(el.dataset.choice),correct=ALL_DAYS.find(d=>d.id===id).correct;s.choice=choice;if(choice===correct){s.quizPassed=true}else{s.wrong++;s.quizPassed=false}});break;
case 'copy-code':copyText(SNIPPETS[id]||'');break;
case 'add-minutes':{const m=Number(el.dataset.minutes)||0;state.minutes[id]=(state.minutes[id]||0)+m;save();render();toast(`${m} minutes logged`);break}
case 'lab-select':ui.lab=el.dataset.lab;render();break;
case 'project-expand':ui.projectOpen=ui.projectOpen===week?0:week;render();break;
case 'rate-skill':state.readiness[el.dataset.skill]=Number(el.dataset.rating);save();render();break;
case 'readiness-plan':ui.readinessPlan=true;render();break;
case 'theme':setTheme(state.theme==='dark'?'light':'dark');break;
case 'set-theme':setTheme(el.dataset.theme);break;
case 'timer-toggle':focusToggle();break;
case 'timer-reset':focusReset();break;
case 'export':exportState();break;
case 'import':document.getElementById('importFile').click();break;
case 'reset':if(confirm('Delete all local learning progress, notes, quiz results and projects? Export a backup first.')){const oldTheme=state.theme;state=defaultState();state.theme=oldTheme;save();render();toast('Learning progress reset')}break;
default:console.warn('Unknown action',action)} }
document.addEventListener('click',ev=>{if(!ev.target.closest('[data-dd]'))CLOSE_DD();const a=ev.target.closest('[data-action]');if(!a)return;if(a.tagName==='INPUT'&&a.type==='checkbox')return;ev.preventDefault();doClick(a.dataset.action,a)});
document.addEventListener('change',ev=>{const el=ev.target,act=el.dataset.action;if(el.dataset.change==='week'){ui.week=Number(el.value);if(ui.route==='learn')ui.day=WEEKS[ui.week-1].days[0].id;render();return}
if(el.type==='checkbox')switch(act){case 'learned':changeDay(el.dataset.day,s=>s.learned=el.checked);return;case 'practice-step':changeDay(el.dataset.day,s=>s.steps[Number(el.dataset.index)]=el.checked);return;case 'project-task':{const p=projectState('w'+el.dataset.week);p.tasks[Number(el.dataset.index)]=el.checked;save();render();if(p.tasks.every(Boolean))toast('Project checklist complete');return}case 'lab-done':state.labs[el.dataset.lab]=el.checked;save();render();return;default:break}
if(el.dataset.input==='lab'){state.labValues[el.dataset.key]=el.value;save();updateLabOutput()}});
document.addEventListener('input',ev=>{const el=ev.target;switch(el.dataset.input){case 'note':dayState(el.dataset.day).notes=el.value.slice(0,12000);save();break;
case 'project-evidence':projectState('w'+el.dataset.week).evidence=el.value.slice(0,1200);save();break;
case 'project-note':projectState('w'+el.dataset.week).notes=el.value.slice(0,12000);save();break;
case 'lab':state.labValues[el.dataset.key]=el.value;if(el.id&&el.id.startsWith('lab-')){const target=document.getElementById('v-'+el.dataset.key);if(target)target.textContent=el.value}save();updateLabOutput();break;
case 'search':ui.search=el.value;document.getElementById('searchResults').innerHTML=renderSearchResults();iconRefresh();break;
default:break}});
document.getElementById('overlay').addEventListener('click',()=>{document.getElementById('overlay').classList.remove('open');document.getElementById('sidebar').classList.remove('open')});
document.getElementById('importFile').addEventListener('change',async ev=>{const f=ev.target.files?.[0];if(!f)return;try{if(f.size>4_000_000)throw new Error('Backup is too large (4 MB maximum)');const parsed=JSON.parse(await f.text());if(!validateImport(parsed))throw new Error('This is not a supported FORM / AI progress export');if(!confirm('Replace current progress with this backup? Export your current data first.'))return;state=normalizeState(parsed);applyTheme();save();navigate('dashboard');toast('Progress restored from backup')}catch(err){alert('Import failed: '+err.message)}finally{ev.target.value=''}});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();navigate('search');document.getElementById('course-search')?.focus()}if(ev.key==='Escape'){CLOSE_DD();document.getElementById('overlay').classList.remove('open');document.getElementById('sidebar').classList.remove('open')}
 const openDD=document.activeElement?.closest?.('.dd.open');if(openDD&&(ev.key==='ArrowDown'||ev.key==='ArrowUp')){ev.preventDefault();const opts=[...openDD.querySelectorAll('.dd-opt')];const idx=opts.indexOf(document.activeElement);const next=ev.key==='ArrowDown'?Math.min(opts.length-1,idx+1):Math.max(0,idx-1);opts[next]?.focus()}});
// Launch after DOM is ready so optional deferred CDNs may enhance the UI.
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initPersistence);else initPersistence();
